INSERT INTO mini_zoo (id, nama, deskripsi, img_url, is_active, created_at, created_by, updated_at, updated_by) VALUES
(gen_random_uuid(), 'Singa Afrika', 'Singa jantan dewasa dari savana Afrika Timur, dikenal dengan surai lebatnya yang mengesankan. Hewan ini merupakan predator puncak yang hidup berkelompok disebut pride.', 'https://storage.ngrembel-asri.com/mini-zoo/singa-afrika.jpg', TRUE, NOW() - INTERVAL '90 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Harimau Sumatera', 'Harimau Sumatera adalah subspesies harimau terkecil yang masih bertahan hidup. Termasuk hewan langka dan dilindungi, merupakan kebanggaan fauna Indonesia.', 'https://storage.ngrembel-asri.com/mini-zoo/harimau-sumatera.jpg', TRUE, NOW() - INTERVAL '89 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Gajah Sumatera', 'Gajah Sumatera adalah subspesies gajah Asia yang lebih kecil dari gajah Afrika. Dikenal cerdas dan memiliki ikatan sosial yang kuat dalam kelompoknya.', 'https://storage.ngrembel-asri.com/mini-zoo/gajah-sumatera.jpg', TRUE, NOW() - INTERVAL '88 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Orangutan Kalimantan', 'Primata besar asli hutan hujan Kalimantan ini termasuk spesies terancam punah. Orangutan dikenal memiliki kecerdasan tinggi dan menggunakan alat sederhana.', 'https://storage.ngrembel-asri.com/mini-zoo/orangutan-kalimantan.jpg', TRUE, NOW() - INTERVAL '87 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Komodo', 'Biawak komodo adalah kadal terbesar di dunia yang hanya ditemukan di beberapa pulau Indonesia. Hewan ini memiliki air liur berbakteri dan kemampuan memanjat pohon.', 'https://storage.ngrembel-asri.com/mini-zoo/komodo.jpg', TRUE, NOW() - INTERVAL '86 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Merak Hijau', 'Merak hijau Jawa adalah burung berbulu indah yang menjadi ikon Pulau Jawa. Jantan memiliki ekor panjang bercorak warna-warni yang dikembangkan saat musim kawin.', 'https://storage.ngrembel-asri.com/mini-zoo/merak-hijau.jpg', TRUE, NOW() - INTERVAL '85 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kuda Nil Pygmy', 'Kuda nil kerdil adalah spesies langka dari Afrika Barat yang jauh lebih kecil dari kuda nil biasa. Hewan nokturnal ini lebih suka hidup soliter di hutan dan rawa.', 'https://storage.ngrembel-asri.com/mini-zoo/kuda-nil-pygmy.jpg', TRUE, NOW() - INTERVAL '84 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Zebra Plains', 'Zebra dataran Afrika dikenal dengan corak belang hitam-putih yang unik pada setiap individunya. Hewan sosial ini hidup dalam kawanan besar di sabana Afrika.', 'https://storage.ngrembel-asri.com/mini-zoo/zebra-plains.jpg', TRUE, NOW() - INTERVAL '83 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Cheetah', 'Cheetah adalah mamalia darat tercepat di dunia, mampu berlari hingga 120 km/jam. Berbeda dari kucing besar lainnya, cheetah tidak bisa mengaum melainkan mendengkur.', 'https://storage.ngrembel-asri.com/mini-zoo/cheetah.jpg', TRUE, NOW() - INTERVAL '82 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Beruang Madu', 'Beruang madu adalah beruang terkecil di dunia dan merupakan satwa asli Asia Tenggara termasuk Indonesia. Hewan ini sangat menyukai madu dan buah-buahan tropis.', 'https://storage.ngrembel-asri.com/mini-zoo/beruang-madu.jpg', TRUE, NOW() - INTERVAL '81 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Rusa Timor', 'Rusa Timor adalah spesies rusa endemik Indonesia yang tersebar di Nusa Tenggara. Jantan memiliki tanduk bercabang yang rontok dan tumbuh kembali setiap tahun.', 'https://storage.ngrembel-asri.com/mini-zoo/rusa-timor.jpg', TRUE, NOW() - INTERVAL '80 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Burung Cendrawasih', 'Burung cendrawasih dijuluki "burung surga" karena keindahan bulunya yang luar biasa. Endemik Papua dan Papua Nugini, burung ini menjadi simbol kebanggaan daerah timur Indonesia.', 'https://storage.ngrembel-asri.com/mini-zoo/cendrawasih.jpg', TRUE, NOW() - INTERVAL '79 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kura-kura Aldabra', 'Kura-kura raksasa Aldabra berasal dari Atol Aldabra di Samudra Hindia. Dapat hidup lebih dari 150 tahun, menjadikannya salah satu hewan dengan umur terpanjang di dunia.', 'https://storage.ngrembel-asri.com/mini-zoo/kura-kura-aldabra.jpg', TRUE, NOW() - INTERVAL '78 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Flamingo', 'Flamingo adalah burung air ikonik dengan bulu merah muda cerah. Warna khas ini berasal dari pigmen karotenoid dalam makanannya. Hidup berkelompok besar di tepi danau berair asin.', 'https://storage.ngrembel-asri.com/mini-zoo/flamingo.jpg', TRUE, NOW() - INTERVAL '77 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Panda Merah', 'Panda merah adalah mamalia kecil dari pegunungan Asia Tengah yang berbeda dari panda raksasa. Aktif di senja hari dan mahir memanjat pohon, memakan bambu dan buah-buahan.', 'https://storage.ngrembel-asri.com/mini-zoo/panda-merah.jpg', TRUE, NOW() - INTERVAL '76 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Binturong', 'Binturong atau bearcats adalah mamalia Asia Tenggara dengan ekor prehensil yang dapat menggenggam. Uniknya, binturong mengeluarkan aroma seperti popcorn dari kelenjar baunya.', 'https://storage.ngrembel-asri.com/mini-zoo/binturong.jpg', TRUE, NOW() - INTERVAL '75 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Lutung Jawa', 'Lutung Jawa adalah primata endemik Pulau Jawa dengan bulu hitam legam dan bayi berwarna oranye cerah. Hidup di hutan tropis dan memakan daun muda, buah, dan biji-bijian.', 'https://storage.ngrembel-asri.com/mini-zoo/lutung-jawa.jpg', TRUE, NOW() - INTERVAL '74 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Tapir Asia', 'Tapir Asia adalah mamalia herbivora berhidung panjang dengan corak hitam-putih yang kontras. Hewan nokturnal ini merupakan penyebar biji yang penting di ekosistem hutan hujan.', 'https://storage.ngrembel-asri.com/mini-zoo/tapir-asia.jpg', TRUE, NOW() - INTERVAL '73 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Siamang', 'Siamang adalah kera berekor panjang dari Sumatera dan Semenanjung Malaya. Dikenal dengan kantung tenggorokan besar yang menghasilkan suara nyaring untuk menandai wilayah.', 'https://storage.ngrembel-asri.com/mini-zoo/siamang.jpg', TRUE, NOW() - INTERVAL '72 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Macan Tutul Jawa', 'Macan tutul Jawa adalah subspesies macan tutul yang hanya ditemukan di Pulau Jawa. Termasuk hewan kritis terancam punah dengan populasi sangat terbatas di alam liar.', 'https://storage.ngrembel-asri.com/mini-zoo/macan-tutul-jawa.jpg', TRUE, NOW() - INTERVAL '71 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Biawak Air', 'Biawak air adalah kadal semi-akuatik yang tersebar luas di Asia Selatan dan Asia Tenggara. Perenang ulung yang sering ditemukan di sungai, danau, dan daerah berair lainnya.', 'https://storage.ngrembel-asri.com/mini-zoo/biawak-air.jpg', TRUE, NOW() - INTERVAL '70 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Elang Jawa', 'Elang Jawa adalah raptor endemik Pulau Jawa yang menjadi inspirasi lambang negara Garuda Pancasila. Termasuk hewan yang terancam punah akibat kehilangan habitat hutan.', 'https://storage.ngrembel-asri.com/mini-zoo/elang-jawa.jpg', TRUE, NOW() - INTERVAL '69 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Trenggiling Jawa', 'Trenggiling Jawa adalah mamalia bersisik yang saat terancam menggulung diri menjadi bola. Pemakan semut dan rayap ini merupakan salah satu hewan paling banyak diselundupkan di dunia.', 'https://storage.ngrembel-asri.com/mini-zoo/trenggiling-jawa.jpg', TRUE, NOW() - INTERVAL '68 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kukang Jawa', 'Kukang Jawa adalah primata nokturnal lambat yang memiliki mata besar adaptif terhadap gelap. Uniknya, kukang adalah satu-satunya primata berbisa di dunia yang memproduksi racun dari kelenjar di sikunya.', 'https://storage.ngrembel-asri.com/mini-zoo/kukang-jawa.jpg', TRUE, NOW() - INTERVAL '67 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Ular Sanca Kembang', 'Ular sanca kembang atau reticulated python adalah ular terpanjang di dunia. Asli Asia Tenggara termasuk Indonesia, ular ini bisa mencapai panjang lebih dari 6 meter.', 'https://storage.ngrembel-asri.com/mini-zoo/sanca-kembang.jpg', TRUE, NOW() - INTERVAL '66 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kakatua Raja', 'Kakatua raja atau palm cockatoo adalah burung ikonik dari Papua dengan jambul besar dan pipi merah. Jantan terkenal karena perilaku uniknya menabuh ranting untuk menarik perhatian betina.', 'https://storage.ngrembel-asri.com/mini-zoo/kakatua-raja.jpg', TRUE, NOW() - INTERVAL '65 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Singa Laut', 'Singa laut California adalah mamalia laut yang dikenal cerdas dan mudah dilatih. Koloni mereka sering terlihat berjemur di dermaga dan bebatuan pantai pesisir Pasifik.', 'https://storage.ngrembel-asri.com/mini-zoo/singa-laut.jpg', TRUE, NOW() - INTERVAL '64 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Penguin Humboldt', 'Penguin Humboldt berasal dari pantai Pasifik Amerika Selatan dan termasuk penguin beriklim sedang. Berbeda dari penguin kutub, mereka hidup di daerah yang relatif lebih hangat.', 'https://storage.ngrembel-asri.com/mini-zoo/penguin-humboldt.jpg', TRUE, NOW() - INTERVAL '63 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Jerapah', 'Jerapah adalah hewan tertinggi di dunia dengan leher panjang khasnya. Mamalia herbivora Afrika ini dapat mencapai tinggi hingga 6 meter dan memiliki jantung terbesar di antara mamalia darat.', 'https://storage.ngrembel-asri.com/mini-zoo/jerapah.jpg', TRUE, NOW() - INTERVAL '62 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kuda Nil', 'Kuda nil adalah mamalia semi-akuatik terbesar ketiga di dunia. Meski terlihat lamban, kuda nil adalah hewan yang sangat berbahaya dan agresif jika merasa terancam.', 'https://storage.ngrembel-asri.com/mini-zoo/kuda-nil.jpg', TRUE, NOW() - INTERVAL '61 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Babi Hutan Jawa', 'Babi hutan Jawa adalah mamalia omnivora endemik Pulau Jawa. Hewan cerdas ini hidup di hutan tropis dan berperan penting sebagai penyebar biji dalam ekosistem hutan.', 'https://storage.ngrembel-asri.com/mini-zoo/babi-hutan-jawa.jpg', TRUE, NOW() - INTERVAL '60 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kasuari Gelambir Ganda', 'Kasuari gelambir ganda adalah burung tidak dapat terbang terbesar kedua di dunia setelah burung unta. Asli Papua dan Australia Utara, burung ini memiliki kaki bertenaga yang dapat mematikan.', 'https://storage.ngrembel-asri.com/mini-zoo/kasuari.jpg', TRUE, NOW() - INTERVAL '59 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Anoa', 'Anoa adalah kerbau kerdil endemik Sulawesi yang merupakan bovid terkecil di dunia. Hewan yang pemalu dan soliter ini kini terancam punah akibat perburuan dan deforestasi.', 'https://storage.ngrembel-asri.com/mini-zoo/anoa.jpg', TRUE, NOW() - INTERVAL '58 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Babirusa', 'Babirusa adalah babi liar unik dari Sulawesi yang memiliki taring atas menembus moncongnya dan melengkung ke atas. Hewan endemik ini merupakan salah satu suidae paling primitif.', 'https://storage.ngrembel-asri.com/mini-zoo/babirusa.jpg', TRUE, NOW() - INTERVAL '57 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Tarsius', 'Tarsius adalah primata malam terkecil di dunia dengan mata besar yang tidak bisa berputar. Primata endemik Asia Tenggara ini mampu memutar kepalanya hampir 180 derajat seperti burung hantu.', 'https://storage.ngrembel-asri.com/mini-zoo/tarsius.jpg', TRUE, NOW() - INTERVAL '56 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Buaya Muara', 'Buaya muara adalah reptil terbesar di dunia yang dapat mencapai panjang lebih dari 6 meter. Predator puncak ini tersebar di pesisir Asia Selatan, Asia Tenggara, hingga Australia Utara.', 'https://storage.ngrembel-asri.com/mini-zoo/buaya-muara.jpg', TRUE, NOW() - INTERVAL '55 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Owa Jawa', 'Owa Jawa adalah gibbon endemik Pulau Jawa yang terancam kritis. Dikenal dengan suara merdu dan kemampuan berayun di antara pohon dengan kecepatan tinggi menggunakan lengan panjangnya.', 'https://storage.ngrembel-asri.com/mini-zoo/owa-jawa.jpg', TRUE, NOW() - INTERVAL '54 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Landak Jawa', 'Landak Jawa adalah mamalia pengerat berukuran besar yang tubuhnya ditutupi duri tajam sebagai pertahanan diri. Hewan nokturnal ini aktif mencari akar, umbi, dan buah di malam hari.', 'https://storage.ngrembel-asri.com/mini-zoo/landak-jawa.jpg', TRUE, NOW() - INTERVAL '53 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Musang Luwak', 'Musang luwak atau Asian palm civet terkenal karena menghasilkan kopi luwak, kopi termahal di dunia. Hewan malam ini berperan sebagai penyebar biji buah-buahan di hutan tropis.', 'https://storage.ngrembel-asri.com/mini-zoo/musang-luwak.jpg', TRUE, NOW() - INTERVAL '52 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Monyet Ekor Panjang', 'Monyet ekor panjang atau kera abu-abu adalah primata yang sangat adaptif dan tersebar luas di Asia Tenggara. Hewan sosial ini hidup dalam kelompok besar dan dikenal cerdas serta oportunistik.', 'https://storage.ngrembel-asri.com/mini-zoo/monyet-ekor-panjang.jpg', TRUE, NOW() - INTERVAL '51 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kancil', 'Kancil atau mouse deer adalah artiodaktil terkecil di dunia yang terkenal dalam cerita rakyat Asia Tenggara. Meski bertubuh mungil, kancil dikenal cerdas dan gesit menghindari predator.', 'https://storage.ngrembel-asri.com/mini-zoo/kancil.jpg', TRUE, NOW() - INTERVAL '50 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kanguru Pohon Mantel', 'Kanguru pohon mantel adalah marsupial dari Papua dan Queensland Australia yang telah berevolusi untuk hidup di atas pohon. Berbeda dari kanguru darat, mereka bisa bergerak maju dan mundur.', 'https://storage.ngrembel-asri.com/mini-zoo/kanguru-pohon.jpg', TRUE, NOW() - INTERVAL '49 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kelelawar Kalong', 'Kalong atau flying fox adalah kelelawar buah terbesar di dunia dengan rentang sayap mencapai 1,7 meter. Hewan malam ini sangat penting bagi ekosistem sebagai penyerbuk tanaman hutan.', 'https://storage.ngrembel-asri.com/mini-zoo/kalong.jpg', TRUE, NOW() - INTERVAL '48 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Tokek Gecko Raksasa', 'Tokek adalah cicak berbintik biru-oranye yang dikenal dengan suara panggilannya yang khas "to-kek". Reptil nocturnal ini merupakan predator alami serangga di lingkungan tropis.', 'https://storage.ngrembel-asri.com/mini-zoo/tokek-gecko.jpg', TRUE, NOW() - INTERVAL '47 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Iguana Hijau', 'Iguana hijau adalah kadal arboreal besar dari Amerika Tengah dan Selatan yang kini banyak dipelihara. Herbivora sejati ini dapat mencapai panjang 2 meter dan hidup hingga 20 tahun.', 'https://storage.ngrembel-asri.com/mini-zoo/iguana-hijau.jpg', FALSE, NOW() - INTERVAL '46 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Nuri Bayan', 'Nuri bayan atau Eclectus parrot adalah burung beo dimorfis mencolok dari Papua. Jantan berwarna hijau cerah sementara betina berwarna merah dan biru, sempat diduga dua spesies berbeda.', 'https://storage.ngrembel-asri.com/mini-zoo/nuri-bayan.jpg', TRUE, NOW() - INTERVAL '45 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Jalak Bali', 'Jalak Bali adalah burung endemik Pulau Bali yang hampir punah dengan bulu putih bersih dan topeng biru di sekitar matanya. Kini dilindungi ketat dan menjadi program penangkaran prioritas nasional.', 'https://storage.ngrembel-asri.com/mini-zoo/jalak-bali.jpg', TRUE, NOW() - INTERVAL '44 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kepiting Kenari', 'Kepiting kenari atau coconut crab adalah arthropoda darat terbesar di dunia yang mampu memanjat pohon kelapa. Krustasea raksasa ini bisa mencapai bobot 4 kg dengan rentang kaki 1 meter.', 'https://storage.ngrembel-asri.com/mini-zoo/kepiting-kenari.jpg', TRUE, NOW() - INTERVAL '43 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Kuda Przewalski', 'Kuda Przewalski adalah satu-satunya kuda liar sejati yang masih hidup di dunia. Berbeda dari kuda domestik, mereka tidak pernah dijinakkan dan memiliki kromosom lebih banyak dari kuda biasa.', 'https://storage.ngrembel-asri.com/mini-zoo/kuda-przewalski.jpg', FALSE, NOW() - INTERVAL '42 days', NULL, NULL, NULL),
(gen_random_uuid(), 'Ular Pelangi', 'Ular pelangi Sundaland adalah ular semi-akuatik dari Asia Tenggara yang memiliki sisik berkilau warna-warni seperti pelangi. Hewan pemalu ini jarang terlihat karena lebih suka bersembunyi di lumpur.', 'https://storage.ngrembel-asri.com/mini-zoo/ular-pelangi.jpg', TRUE, NOW() - INTERVAL '41 days', NULL, NULL, NULL);